import re

def audit(namespaces, pods, revisions, tags, default_revision):
    def name(value):
        return isinstance(value,str) and re.fullmatch(r'[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?',value)
    if (not isinstance(revisions,list) or not revisions or not all(name(v) for v in revisions)
            or len(set(revisions))!=len(revisions) or default_revision not in revisions
            or not isinstance(tags,dict) or not all(name(k) and v in revisions for k,v in tags.items())
            or set(tags)&set(revisions) or not isinstance(namespaces,list) or not isinstance(pods,list)):
        raise ValueError('invalid revision inventory')
    known={};seen=set();out=[]
    for ns in namespaces:
        if not isinstance(ns,dict) or set(ns)!={'name','labels'} or not name(ns['name']) or ns['name'] in known:
            raise ValueError('invalid namespace')
        labels=ns['labels']
        if not isinstance(labels,dict) or not all(isinstance(k,str) and isinstance(v,str) for k,v in labels.items()):
            raise ValueError('invalid labels')
        if 'istio-injection' in labels and labels['istio-injection'] not in ('enabled','disabled'):
            raise ValueError('invalid legacy injection label')
        if 'istio.io/rev' in labels and not name(labels['istio.io/rev']):raise ValueError('invalid revision label')
        known[ns['name']]=dict(labels)
    for pod in pods:
        if not isinstance(pod,dict) or set(pod)!={'name','namespace','inject','proxy_revision'}:
            raise ValueError('invalid pod record')
        if (not name(pod['name']) or not name(pod['namespace']) or pod['namespace'] not in known or pod['inject'] not in (None,'true','false')
                or (pod['proxy_revision'] is not None and not name(pod['proxy_revision']))):
            raise ValueError('invalid pod evidence')
        identity=(pod['namespace'],pod['name'])
        if identity in seen:raise ValueError('duplicate pod')
        seen.add(identity);labels=known[pod['namespace']];reasons=[]
        legacy=labels.get('istio-injection');revision=labels.get('istio.io/rev')
        if legacy is not None and revision is not None:reasons.append('label_conflict')
        expected=False;desired=None
        if legacy=='disabled' or pod['inject']=='false':pass
        elif legacy=='enabled':expected=True;desired=default_revision
        elif revision is not None:
            desired=revision
            if desired is None:expected=None;reasons.append('unresolved_revision')
            else:expected=True
        elif pod['inject']=='true':expected=True;desired=default_revision
        actual=pod['proxy_revision']
        if expected is True and actual is None:reasons.append('missing_proxy')
        elif expected is False and actual is not None:reasons.append('unexpected_proxy')
        elif expected is True and actual!=desired:reasons.append('revision_drift')
        out.append({'namespace':identity[0],'name':identity[1],'expected_injected':expected,
                    'desired_revision':desired,'actual_revision':actual,'reasons':reasons})
    return {'pods':sorted(out,key=lambda p:(p['namespace'],p['name'])),'live_verified':False}

