metric_identity_dropped.task.py:
import itertools,re

def plan(samples, protected, costs, budget):
    if (not isinstance(samples,list) or len(samples)>500 or not isinstance(protected,list)
            or not all(isinstance(x,str) for x in protected) or len(set(protected))!=len(protected)
            or not isinstance(costs,dict) or type(budget) is not int or budget<0):
        raise ValueError('invalid planning inputs')
    rows=[];dimensions=set()
    for sample in samples:
        if not isinstance(sample,dict) or set(sample)!={'metric','labels'}:raise ValueError('invalid series')
        metric,labels=sample['metric'],sample['labels']
        if (not isinstance(metric,str) or not re.fullmatch(r'[A-Za-z_:][A-Za-z0-9_:]*',metric)
                or not isinstance(labels,dict) or not all(isinstance(k,str) and k!='__name__'
                    and re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*',k) and isinstance(v,str) for k,v in labels.items())):
            raise ValueError('invalid series labels')
        dimensions.update(labels);rows.append((metric,tuple(sorted(labels.items()))))
    if (len(dimensions)>10 or not set(protected)<=dimensions or set(costs)!=dimensions-set(protected)
            or not all(type(v)is int and v>=0 for v in costs.values())):raise ValueError('invalid dimension policy')
    unique=set(rows);optional=sorted(costs);best=None
    for size in range(len(optional)+1):
        for drop in itertools.combinations(optional,size):
            removed=set(drop)
            count=len({tuple((k,v) for k,v in labels if k not in removed) for metric,labels in unique})
            if count<=budget:
                rank=(sum(costs[k] for k in drop),len(drop),drop)
                if best is None or rank<best[0]:best=(rank,count)
    before=len(unique)
    if best is None:return {'feasible':False,'drop':None,'cost':None,'series_before':before,'series_after':None,'collapsed':None,'changes_applied':False}
    rank,after=best
    return {'feasible':True,'drop':list(rank[2]),'cost':rank[0],'series_before':before,
            'series_after':after,'collapsed':before-after,'changes_applied':False}

